export const THEME_CSS: string = "/*\n * dsh-ps-floating-panels — theme layer.\n *\n * Colour ONLY. Every value is a `var(--dsw-alias-*, <fallback>)` so the panels\n * follow the host's light/dark theme: when the host defines the alias token the\n * token wins, and the fallback keeps the panel legible when it is absent.\n *\n * Geometry (positioning, flex, sizing, transitions) lives in inject-css.ts\n * under the `ps-` class names, so this file never has to restate layout.\n *\n * The fallbacks are plain hex/rgb literals by necessity — a CSS custom\n * property needs a concrete value to fall back to. They are NOT stray colours:\n * they are always inside the second argument of `var()`.\n */\n\n.ps-floating-root {\n  color: var(--dsw-alias-label-primary, #1c1c1e);\n  font-size: 13px;\n  line-height: 1.45;\n}\n\n/* Outer Dockview container: the ONE place rounded corners are applied. Adopted\n * native DSH elements are never re-rounded / re-bordered — only their position\n * is neutralised (see inject-css.ts). */\n.ps-dock-shell {\n  background: var(--dsw-alias-bg-layer-1, #ffffff);\n  border: 1px solid var(--dsw-alias-border-l1, rgba(0, 0, 0, 0.12));\n  border-radius: 12px;\n  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.22);\n  overflow: hidden;\n}\n\n.ps-dock-toolbar {\n  background: var(--dsw-alias-bg-layer-2, #f5f5f7);\n  border-bottom: 1px solid var(--dsw-alias-border-l1, rgba(0, 0, 0, 0.12));\n  color: var(--dsw-alias-label-secondary, #6b6b70);\n}\n\n.ps-dock-toolbar__title {\n  color: var(--dsw-alias-label-primary, #1c1c1e);\n  font-weight: 600;\n}\n\n.ps-dock-btn {\n  background: transparent;\n  border: 1px solid var(--dsw-alias-border-l1, rgba(0, 0, 0, 0.14));\n  border-radius: 6px;\n  color: var(--dsw-alias-label-secondary, #6b6b70);\n  cursor: pointer;\n}\n\n.ps-dock-btn:hover {\n  background: var(--dsw-alias-bg-layer-1, #ffffff);\n  color: var(--dsw-alias-label-primary, #1c1c1e);\n  border-color: var(--dsw-alias-brand-primary, #4d6bfe);\n}\n\n.ps-dock-btn:focus-visible {\n  outline: 2px solid var(--dsw-alias-brand-primary, #4d6bfe);\n  outline-offset: 1px;\n}\n\n/* Tab bar (our defaultTabComponent) */\n.ps-tab {\n  color: var(--dsw-alias-label-secondary, #6b6b70);\n}\n\n.ps-tab[data-active='true'] {\n  color: var(--dsw-alias-label-primary, #1c1c1e);\n}\n\n.ps-tab__label {\n  color: inherit;\n}\n\n.ps-tab__btn {\n  color: var(--dsw-alias-label-tertiary, #9a9aa0);\n  background: transparent;\n  border: none;\n  border-radius: 4px;\n  cursor: pointer;\n}\n\n.ps-tab__btn:hover {\n  color: var(--dsw-alias-label-primary, #1c1c1e);\n  background: var(--dsw-alias-bg-layer-2, #f0f0f2);\n}\n\n/* Panel content */\n.ps-panel-body {\n  background: var(--dsw-alias-bg-base, #ffffff);\n  color: var(--dsw-alias-label-primary, #1c1c1e);\n}\n\n.ps-panel-body[data-collapsed='true'] {\n  background: var(--dsw-alias-bg-layer-2, #f5f5f7);\n}\n\n.ps-panel-hint {\n  color: var(--dsw-alias-label-tertiary, #9a9aa0);\n}\n\n/* Adopted host region. The host node keeps its own colours; this only paints\n * the panel behind it while the node is (re)attached. */\n.ps-native-host {\n  background: var(--dsw-alias-bg-base, #ffffff);\n}\n\n/* Region the host no longer exposes (its pane was closed) */\n.ps-panel-missing {\n  background: var(--dsw-alias-bg-layer-2, #f5f5f7);\n  color: var(--dsw-alias-label-secondary, #6b6b70);\n}\n\n.ps-panel-missing__title {\n  color: var(--dsw-alias-label-primary, #1c1c1e);\n  font-weight: 600;\n}\n\n.ps-panel-missing__body {\n  color: var(--dsw-alias-label-secondary, #6b6b70);\n}\n\n.ps-panel-missing__hint {\n  color: var(--dsw-alias-label-tertiary, #9a9aa0);\n}\n\n/* Status badge — not rendered at all when showStatusBadge is false */\n.ps-status-badge {\n  background: var(--dsw-alias-bg-layer-1, #ffffff);\n  border: 1px solid var(--dsw-alias-border-l1, rgba(0, 0, 0, 0.12));\n  border-radius: 999px;\n  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.18);\n  color: var(--dsw-alias-label-secondary, #6b6b70);\n}\n\n.ps-status-badge__dot {\n  background: var(--dsw-alias-state-success-primary, #22c55e);\n}\n\n.ps-status-badge__dot[data-floating='true'] {\n  background: var(--dsw-alias-state-business-primary, #4d6bfe);\n}\n\n.ps-status-badge__dot[data-collapsed='true'] {\n  background: var(--dsw-alias-state-warn-primary, #f59e0b);\n}\n\n.ps-launcher-pill {\n  background: var(--dsw-alias-bg-layer-1, #ffffff);\n  border: 1px solid var(--dsw-alias-border-l1, rgba(0, 0, 0, 0.12));\n  border-radius: 999px;\n  color: var(--dsw-alias-label-secondary, #6b6b70);\n  cursor: pointer;\n  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.18);\n}\n\n.ps-launcher-pill:hover {\n  color: var(--dsw-alias-label-primary, #1c1c1e);\n  border-color: var(--dsw-alias-brand-primary, #4d6bfe);\n}\n\n.ps-launcher-pill__count {\n  background: var(--dsw-alias-brand-primary, #4d6bfe);\n  color: var(--dsw-alias-label-primary-foreground, #ffffff);\n}\n\n/* Conflict dialog */\n.ps-conflict-backdrop {\n  background: var(--dsw-alias-bg-mask, rgba(0, 0, 0, 0.42));\n}\n\n.ps-conflict-dialog {\n  background: var(--dsw-alias-bg-layer-1, #ffffff);\n  border: 1px solid var(--dsw-alias-border-l1, rgba(0, 0, 0, 0.12));\n  border-radius: 12px;\n  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.32);\n  color: var(--dsw-alias-label-primary, #1c1c1e);\n}\n\n.ps-conflict-dialog__title {\n  color: var(--dsw-alias-state-warn-primary, #f59e0b);\n  font-weight: 600;\n}\n\n.ps-conflict-dialog__list {\n  color: var(--dsw-alias-label-primary, #1c1c1e);\n}\n\n.ps-conflict-dialog__hint {\n  color: var(--dsw-alias-label-secondary, #6b6b70);\n}\n"
